:root {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --border: #e2e7ee;
  --text: #1b2533;
  --muted: #5b6878;
  --primary: #0f2a4a;       /* azul escuro */
  --primary-2: #17406e;
  --accent: #2f6fdb;        /* azul de ação */
  --accent-soft: #e8f0fc;
  --danger: #b42318;
  --danger-soft: #fdecea;
  --warn-soft: #fff6e5;
  --fin: #1f6f5c;  --fin-soft: #e6f4ef;
  --int: #2f6fdb;  --int-soft: #e8f0fc;
  --ouv: #8a4b14;  --ouv-soft: #fbf0e4;
  --radius: 10px;
  --shadow: 0 1px 2px rgba(15, 42, 74, .06), 0 2px 8px rgba(15, 42, 74, .05);
  --font: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 15px/1.55 var(--font); -webkit-font-smoothing: antialiased;
  display: flex; flex-direction: column; min-height: 100dvh;
}
button, textarea { font: inherit; color: inherit; }
.sprite { display: none; }
.icon { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor;
  stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* ---------- topo ---------- */
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 12px 24px; background: var(--primary); color: #fff;
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.brand-mark {
  width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center;
  background: #fff; color: var(--primary); font-weight: 700; font-size: 18px;
}
.brand h1 { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: .1px; }
.brand p { margin: 0; font-size: 12.5px; color: #b9c7da; }
.topbar-actions { display: flex; align-items: center; gap: 10px; }
.status-pill {
  font-size: 12.5px; padding: 4px 10px; border-radius: 999px;
  background: rgba(255, 255, 255, .1); color: #dbe5f2; white-space: nowrap;
}
.status-pill.ok::before, .status-pill.warn::before, .status-pill.down::before {
  content: ""; display: inline-block; width: 7px; height: 7px; border-radius: 50%;
  margin-right: 6px; vertical-align: 1px;
}
.status-pill.ok::before { background: #4ade80; }
.status-pill.warn::before { background: #fbbf24; }
.status-pill.down::before { background: #f87171; }

.btn {
  display: inline-flex; align-items: center; gap: 8px; border: 1px solid transparent;
  border-radius: 8px; padding: 8px 14px; cursor: pointer; font-weight: 500;
  transition: background-color .15s ease, border-color .15s ease, opacity .15s ease;
}
.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:not(:disabled):hover { background: #2560c4; }
.btn-ghost { background: transparent; color: #fff; border-color: rgba(255, 255, 255, .28); }
.btn-ghost:hover { background: rgba(255, 255, 255, .08); }

/* ---------- layout ---------- */
.layout {
  flex: 1; display: grid; grid-template-columns: 280px minmax(0, 1fr);
  gap: 20px; width: 100%; max-width: 1200px; margin: 0 auto; padding: 20px 24px; min-height: 0;
}
.sidebar { display: flex; flex-direction: column; gap: 12px; }
.sidebar-title { margin: 0; font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); font-weight: 600; }
.domain-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.domain-card {
  display: flex; gap: 12px; align-items: flex-start; padding: 12px 14px;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow); border-left: 3px solid var(--d, var(--accent));
}
.domain-card .icon { color: var(--d); margin-top: 2px; }
.domain-card strong { display: block; font-size: 14px; }
.domain-card span { display: block; font-size: 13px; color: var(--muted); line-height: 1.4; }
.domain-card .doc-count { margin-top: 4px; font-size: 12px; color: var(--muted); }
[data-domain="financeiro"] { --d: var(--fin); --d-soft: var(--fin-soft); }
[data-domain="informacoes_internas"] { --d: var(--int); --d-soft: var(--int-soft); }
[data-domain="ouvidoria"] { --d: var(--ouv); --d-soft: var(--ouv-soft); }
[data-domain="indefinido"] { --d: var(--muted); --d-soft: #eef1f5; }
.sidebar-note { margin: 4px 0 0; font-size: 12.5px; color: var(--muted); line-height: 1.5; }

/* ---------- conversa ---------- */
.chat {
  display: flex; flex-direction: column; min-height: 0; min-width: 0;
  background: var(--surface); border: 1px solid var(--border); border-radius: 12px; box-shadow: var(--shadow);
}
.messages {
  flex: 1; overflow-y: auto; padding: 24px; display: flex; flex-direction: column; gap: 18px;
  min-height: 320px; max-height: calc(100dvh - 230px); scroll-behavior: smooth;
}
.empty-state { margin: auto 0; max-width: 680px; }
.empty-state h2 { margin: 0 0 6px; font-size: 20px; color: var(--primary); font-weight: 600; }
.empty-state p { margin: 0 0 16px; color: var(--muted); }
.suggestions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.suggestion {
  text-align: left; padding: 10px 12px; border-radius: 8px; cursor: pointer;
  background: var(--surface-2); border: 1px solid var(--border); border-left: 3px solid var(--d);
  font-size: 13.5px; line-height: 1.4; transition: border-color .15s ease, background-color .15s ease;
}
.suggestion:hover { background: var(--d-soft); border-color: var(--d); }

.msg { display: flex; flex-direction: column; max-width: 82%; }
.msg-user { align-self: flex-end; align-items: flex-end; }
.msg-assistant { align-self: flex-start; }
.bubble { padding: 11px 14px; border-radius: 12px; white-space: normal; overflow-wrap: anywhere; }
.msg-user .bubble { background: var(--primary); color: #fff; border-bottom-right-radius: 4px; }
.msg-assistant .bubble {
  background: var(--surface); border: 1px solid var(--border); border-bottom-left-radius: 4px;
  border-left: 3px solid var(--d, var(--border));
}
.bubble p { margin: 0 0 8px; } .bubble p:last-child { margin-bottom: 0; }
.bubble ul { margin: 4px 0 8px; padding-left: 20px; }
.meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-bottom: 6px; font-size: 12px; color: var(--muted); }
.badge {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 999px;
  font-weight: 600; font-size: 11.5px; background: var(--d-soft); color: var(--d);
}
.tag { padding: 2px 8px; border-radius: 999px; background: #eef1f5; font-size: 11.5px; }
.notice { margin-top: 8px; font-size: 12.5px; color: var(--muted); padding: 6px 10px; background: var(--warn-soft); border-radius: 6px; }
.msg-error .bubble { background: var(--danger-soft); border-color: #f5c2bd; border-left-color: var(--danger); color: #7a1a12; }
.msg-error .bubble .icon { color: var(--danger); vertical-align: -3px; margin-right: 6px; }
.retry { margin-top: 8px; background: #fff; border: 1px solid #f5c2bd; color: var(--danger); padding: 5px 10px; font-size: 13px; }

.sources { margin-top: 8px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); }
.sources summary { cursor: pointer; padding: 7px 10px; font-size: 13px; font-weight: 500; color: var(--primary-2); list-style: none; display: flex; gap: 6px; align-items: center; }
.sources summary::-webkit-details-marker { display: none; }
.sources summary::after { content: "▾"; margin-left: auto; transition: transform .15s ease; color: var(--muted); }
.sources[open] summary::after { transform: rotate(180deg); }
.sources ol { margin: 0; padding: 0 10px 10px 30px; display: flex; flex-direction: column; gap: 8px; }
.sources li { font-size: 13px; }
.src-doc { font-weight: 600; }
.src-meta { color: var(--muted); font-size: 12px; }
.src-excerpt { margin: 3px 0 0; color: #3b4757; font-size: 12.5px; line-height: 1.45; background: #fff; border: 1px solid var(--border); border-radius: 6px; padding: 6px 8px; }

.loading .bubble { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: 13.5px; }
.dots { display: inline-flex; gap: 4px; }
.dots i { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); animation: blink 1.2s infinite ease-in-out; }
.dots i:nth-child(2) { animation-delay: .15s; } .dots i:nth-child(3) { animation-delay: .3s; }
@keyframes blink { 0%, 80%, 100% { opacity: .25; } 40% { opacity: 1; } }

/* ---------- composer ---------- */
.composer { display: flex; gap: 10px; align-items: flex-end; padding: 14px 16px 6px; border-top: 1px solid var(--border); }
.composer textarea {
  flex: 1; resize: none; min-height: 44px; max-height: 160px; padding: 10px 12px;
  border: 1px solid var(--border); border-radius: 8px; background: var(--surface-2); line-height: 1.45;
}
.composer textarea:focus { outline: none; border-color: var(--accent); background: #fff; box-shadow: 0 0 0 3px var(--accent-soft); }
.composer-side { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.counter { font-size: 11.5px; color: var(--muted); }
.counter.over { color: var(--danger); }
.composer-hint { margin: 0; padding: 0 16px 12px; font-size: 12px; color: var(--muted); }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}

/* ---------- responsivo ---------- */
@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; padding: 12px 16px; gap: 12px; }
  .domain-list { flex-direction: row; overflow-x: auto; scrollbar-width: none; }
  .domain-card { flex: 0 0 auto; padding: 8px 12px; align-items: center; }
  .domain-card span { display: none; }
  .sidebar-title, .sidebar-note { display: none; }
  .messages { max-height: none; padding: 16px; }
  .msg { max-width: 92%; }
}
@media (max-width: 560px) {
  .topbar { padding: 10px 16px; }
  .brand p, .btn-ghost span, #send span { display: none; }
  .status-pill { max-width: 120px; overflow: hidden; text-overflow: ellipsis; }
  .suggestions { grid-template-columns: 1fr; }
  .composer { padding: 10px 12px 4px; }
  .composer textarea { font-size: 16px; } /* evita zoom no iOS */
  .composer-hint { padding: 0 12px 10px; }
}

"use strict";

(() => {
  const API = ""; // mesma origem: o backend FastAPI serve este frontend
  const MAX_CHARS = 1000;
  const TIMEOUT_MS = 60000;

  const CATEGORY = {
    financeiro: "Financeiro",
    informacoes_internas: "Informações internas",
    ouvidoria: "Ouvidoria",
    indefinido: "Domínio não identificado",
  };
  const MODE = {
    deterministic: "Calculado sobre os dados",
    extractive: "Trechos recuperados (sem IA)",
    llm: "Gerado por IA a partir das fontes",
  };
  const STATUS = {
    not_found: "Sem evidência suficiente",
    clarification: "Precisa de esclarecimento",
    refused: "Solicitação recusada",
    out_of_scope: "Fora do escopo",
  };

  const $ = (sel) => document.querySelector(sel);
  const messages = $("#messages");
  const emptyState = $("#empty-state");
  const form = $("#composer");
  const input = $("#question");
  const sendBtn = $("#send");
  const counter = $("#counter");
  const statusPill = $("#service-status");

  let busy = false;
  let controller = null;

  // ---------------------------------------------------------------- utilitários

  function el(tag, attrs = {}, children = []) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (v === undefined || v === null) continue;
      if (k === "class") node.className = v;
      else if (k === "text") node.textContent = v;
      else node.setAttribute(k, v);
    }
    for (const c of [].concat(children)) if (c) node.append(c);
    return node;
  }

  function icon(id) {
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("aria-hidden", "true");
    const use = document.createElementNS("http://www.w3.org/2000/svg", "use");
    use.setAttribute("href", `#${id}`);
    svg.append(use);
    return svg;
  }

  /** Converte o texto da resposta em nós DOM (negrito e listas), sem innerHTML. */
  function inline(text) {
    const frag = document.createDocumentFragment();
    text.split(/(\*\*[^*]+\*\*)/g).forEach((part) => {
      if (/^\*\*[^*]+\*\*$/.test(part)) frag.append(el("strong", { text: part.slice(2, -2) }));
      else if (part) frag.append(document.createTextNode(part));
    });
    return frag;
  }

  function renderText(text) {
    const frag = document.createDocumentFragment();
    let list = null;
    for (const raw of text.split("\n")) {
      const line = raw.trimEnd();
      if (/^\s*[-•]\s+/.test(line)) {
        if (!list) frag.append((list = el("ul")));
        list.append(el("li", {}, inline(line.replace(/^\s*[-•]\s+/, ""))));
      } else if (line.trim()) {
        list = null;
        frag.append(el("p", {}, inline(line)));
      } else {
        list = null;
      }
    }
    return frag;
  }

  function scrollToEnd() {
    messages.scrollTop = messages.scrollHeight;
  }

  // ---------------------------------------------------------------- mensagens

  function addUser(text) {
    emptyState.hidden = true;
    messages.append(el("div", { class: "msg msg-user" }, el("div", { class: "bubble" }, renderText(text))));
    scrollToEnd();
  }

  function sourcesBlock(sources) {
    if (!sources || !sources.length) return null;
    const list = el("ol");
    for (const s of sources) {
      const meta = [s.section ? `seção: ${s.section}` : null, s.page ? `página ${s.page}` : null,
        typeof s.score === "number" && s.score > 0 ? `relevância BM25 ${s.score.toFixed(2)}` : null]
        .filter(Boolean).join(" · ");
      list.append(el("li", {}, [
        el("span", { class: "src-doc", text: s.document }),
        meta ? el("span", { class: "src-meta", text: ` — ${meta}` }) : null,
        el("p", { class: "src-excerpt", text: s.excerpt }),
      ]));
    }
    return el("details", { class: "sources" }, [
      el("summary", {}, [icon("i-doc"), document.createTextNode(`Fontes consultadas (${sources.length})`)]),
      list,
    ]);
  }

  function addAssistant(data) {
    const meta = el("div", { class: "meta" }, [
      el("span", { class: "badge", text: CATEGORY[data.category] || data.category }),
      data.agent ? el("span", { text: data.agent }) : null,
      MODE[data.mode] ? el("span", { class: "tag", text: MODE[data.mode] }) : null,
      STATUS[data.status] ? el("span", { class: "tag", text: STATUS[data.status] }) : null,
      typeof data.confidence === "number"
        ? el("span", { class: "tag", title: "Confiança do roteamento por regras",
          text: `roteamento ${Math.round(data.confidence * 100)}%` })
        : null,
    ]);
    const bubble = el("div", { class: "bubble" }, [renderText(data.answer)]);
    if (data.notice) bubble.append(el("div", { class: "notice", text: data.notice }));
    const src = sourcesBlock(data.sources);
    if (src) bubble.append(src);
    messages.append(el("div", { class: "msg msg-assistant", "data-domain": data.category }, [meta, bubble]));
    scrollToEnd();
  }

  function addError(message, retryQuestion) {
    const bubble = el("div", { class: "bubble" }, [icon("i-alert"), document.createTextNode(message)]);
    if (retryQuestion) {
      const btn = el("button", { class: "btn retry", type: "button", text: "Tentar novamente" });
      btn.addEventListener("click", () => {
        btn.closest(".msg").remove();
        ask(retryQuestion, { echo: false });
      });
      bubble.append(el("div", {}, btn));
    }
    messages.append(el("div", { class: "msg msg-assistant msg-error", role: "alert" }, bubble));
    scrollToEnd();
  }

  // ---------------------------------------------------------------- envio

  function setBusy(value) {
    busy = value;
    sendBtn.disabled = value || !input.value.trim() || input.value.length > MAX_CHARS;
    input.setAttribute("aria-busy", String(value));
  }

  async function ask(question, { echo = true } = {}) {
    if (busy) return; // impede envios duplicados
    if (echo) addUser(question);
    setBusy(true);
    const loading = $("#tpl-loading").content.firstElementChild.cloneNode(true);
    messages.append(loading);
    scrollToEnd();

    controller = new AbortController();
    const timer = setTimeout(() => controller.abort("timeout"), TIMEOUT_MS);
    try {
      const res = await fetch(`${API}/api/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question }),
        signal: controller.signal,
      });
      let body = null;
      try { body = await res.json(); } catch { /* resposta sem JSON */ }
      if (!res.ok) {
        const detail = body && typeof body.detail === "string" ? body.detail : null;
        if (res.status === 422) addError(detail || "Pergunta inválida.");
        else addError(detail || `O serviço respondeu com erro (${res.status}).`, question);
        return;
      }
      addAssistant(body);
    } catch (err) {
      if (controller.signal.aborted && controller.signal.reason === "reset") return;
      if (controller.signal.aborted) addError("A resposta demorou demais. Tente novamente.", question);
      else addError("Não foi possível conectar ao serviço. Verifique se a API está em execução.", question);
      checkHealth();
    } finally {
      clearTimeout(timer);
      loading.remove();
      controller = null;
      setBusy(false);
    }
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const q = input.value.trim();
    if (!q || busy) return;
    if (q.length > MAX_CHARS) return;
    input.value = "";
    updateCounter();
    ask(q);
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
      e.preventDefault();
      form.requestSubmit();
    }
  });

  function updateCounter() {
    const n = input.value.length;
    counter.textContent = `${n}/${MAX_CHARS}`;
    counter.classList.toggle("over", n > MAX_CHARS);
    input.style.height = "auto";
    input.style.height = `${Math.min(input.scrollHeight, 160)}px`;
    setBusy(busy);
  }
  input.addEventListener("input", updateCounter);

  document.querySelectorAll(".suggestion").forEach((btn) =>
    btn.addEventListener("click", () => ask(btn.textContent.trim())));

  $("#new-chat").addEventListener("click", () => {
    if (controller) controller.abort("reset");
    messages.querySelectorAll(".msg").forEach((m) => m.remove());
    emptyState.hidden = false;
    input.value = "";
    updateCounter();
    input.focus();
  });

  // ---------------------------------------------------------------- estado do serviço

  async function checkHealth() {
    try {
      const res = await fetch(`${API}/health`, { cache: "no-store" });
      const h = await res.json();
      if (h.status !== "ok") {
        statusPill.className = "status-pill warn";
        statusPill.textContent = "Base de conhecimento não indexada";
      } else if (h.llm && h.llm.configured) {
        statusPill.className = "status-pill ok";
        statusPill.textContent = `Online · IA: ${h.llm.provider}`;
      } else {
        statusPill.className = "status-pill ok";
        statusPill.textContent = "Online · modo extrativo";
        statusPill.title = (h.llm && h.llm.reason) || "";
      }
    } catch {
      statusPill.className = "status-pill down";
      statusPill.textContent = "Serviço indisponível";
    }
  }

  async function loadDocCounts() {
    try {
      const res = await fetch(`${API}/api/knowledge/status`);
      const st = await res.json();
      document.querySelectorAll(".domain-card").forEach((card) => {
        const d = st.domains && st.domains[card.dataset.domain];
        if (!d) return;
        card.querySelector("div").append(
          el("span", { class: "doc-count", text: `${d.documents} arquivos · ${d.chunks} trechos indexados` }));
      });
    } catch { /* indicador opcional */ }
  }

  updateCounter();
  checkHealth();
  loadDocCounts();
})();

