/* Assistente Aurora — identidade: o arco da aurora sobre a linha do horizonte.
   Paleta: névoa (fundo), papel (superfícies), marinho (marca), céu (ações) e
   uma cor por agente, usada no avatar e nos destaques do próprio agente. */
:root {
  --nevoa: #f2f4f7;
  --papel: #ffffff;
  --papel-2: #f7f9fb;
  --linha: #dde3ea;
  --linha-forte: #c9d2dd;
  --tinta: #172233;
  --tinta-2: #3b4757;
  --muted: #5a6779;
  --marinho: #0e2a47;
  --marinho-2: #183d63;
  --ceu: #2a6fd4;
  --ceu-hover: #225fb8;
  --ceu-suave: #e7f0fc;
  --perigo: #b42318;
  --perigo-suave: #fdeeec;

  --fin: #12806f;  --fin-suave: #e3f3ef;
  --int: #4656c7;  --int-suave: #eaedfa;
  --ouv: #8c3d78;  --ouv-suave: #f6e9f2;
  --aur: #0e2a47;  --aur-suave: #e4eaf2;

  --font: "Segoe UI Variable Text", "Segoe UI", -apple-system, BlinkMacSystemFont, "SF Pro Text",
          system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Segoe UI Variable Display", "Segoe UI", -apple-system, "SF Pro Display",
          system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --topbar-h: 60px;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--nevoa);
  color: var(--tinta);
  font: 15px/1.6 var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button, textarea { font: inherit; color: inherit; }
p { margin: 0; }
.sprite { display: none; }
.icon, .avatar svg, .brand-mark svg, .welcome-mark svg {
  fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round;
}
.icon { width: 18px; height: 18px; flex: none; }
.visually-hidden {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}
:focus-visible { outline: 2px solid var(--ceu); outline-offset: 2px; border-radius: 6px; }

/* Cada domínio define --d (cor) e --d-suave (fundo) para os elementos dentro dele. */
[data-domain="financeiro"] { --d: var(--fin); --d-suave: var(--fin-suave); }
[data-domain="informacoes_internas"] { --d: var(--int); --d-suave: var(--int-suave); }
[data-domain="ouvidoria"] { --d: var(--ouv); --d-suave: var(--ouv-suave); }
[data-domain="indefinido"], [data-domain="aurora"] { --d: var(--aur); --d-suave: var(--aur-suave); }

.avatar {
  width: 36px; height: 36px; flex: none; border-radius: 50%;
  display: grid; place-items: center;
  background: var(--d-suave, var(--aur-suave)); color: var(--d, var(--aur));
}
.avatar svg { width: 19px; height: 19px; }
.avatar.sm { width: 26px; height: 26px; }
.avatar.sm svg { width: 15px; height: 15px; }

/* ---------------------------------------------------------------- topo */
.topbar { background: var(--marinho); color: #fff; height: var(--topbar-h); }
.topbar-inner {
  height: 100%; max-width: 1280px; margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 10px; flex: none;
  display: grid; place-items: center; background: #fff; color: var(--marinho);
}
.brand-mark svg { width: 22px; height: 22px; stroke-width: 2; }
.brand h1 {
  margin: 0; font: 600 16px/1.2 var(--font-display); letter-spacing: -0.005em; white-space: nowrap;
}
.brand-text p { font-size: 12.5px; line-height: 1.3; color: #a9bbd1; }
.topbar-actions { display: flex; align-items: center; gap: 12px; }

.status {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 13px; color: #d3dfec; white-space: nowrap;
}
.status::before {
  content: ""; width: 8px; height: 8px; border-radius: 50%; background: #8aa0b8;
}
.status.ok::before { background: #4ade80; box-shadow: 0 0 0 3px rgba(74, 222, 128, .18); }
.status.warn::before { background: #fbbf24; }
.status.down::before { background: #f87171; }

.btn-new {
  display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 14px;
  border-radius: 10px; border: 1px solid rgba(255, 255, 255, .25); background: transparent;
  color: #fff; font-weight: 500; font-size: 14px; cursor: pointer;
  transition: background-color .15s ease, border-color .15s ease;
}
.btn-new:hover { background: rgba(255, 255, 255, .08); border-color: rgba(255, 255, 255, .4); }
.btn-new .icon { width: 16px; height: 16px; }

/* ---------------------------------------------------------------- layout */
.layout {
  max-width: 1280px; margin: 0 auto; padding: 24px;
  display: grid; grid-template-columns: 272px minmax(0, 1fr); gap: 28px;
  height: calc(100dvh - var(--topbar-h));
}

/* ---------------------------------------------------------------- barra lateral */
.sidebar { min-width: 0; display: flex; flex-direction: column; gap: 14px; padding-top: 6px; overflow-y: auto; }
.side-heading { margin: 0; font: 600 13px/1.4 var(--font); color: var(--muted); }
.side-heading:not(:first-child) { margin-top: 14px; }
.agent-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.agent { display: flex; gap: 12px; align-items: flex-start; padding: 12px 0; border-bottom: 1px solid var(--linha); }
.agent:first-child { padding-top: 4px; }
.agent-text { min-width: 0; }
.agent-name { font-weight: 600; font-size: 14.5px; line-height: 1.35; }
.agent-desc { font-size: 13px; line-height: 1.45; color: var(--muted); margin-top: 2px; }
.agent-count { font-size: 12.5px; color: var(--d); margin-top: 4px; font-weight: 500; }

.steps { margin: 0; padding: 0; list-style: none; counter-reset: step; display: flex; flex-direction: column; gap: 10px; }
.steps li {
  counter-increment: step; position: relative; padding-left: 32px;
  font-size: 13.5px; line-height: 1.45; color: var(--tinta-2);
}
.steps li::before {
  content: counter(step); position: absolute; left: 0; top: -1px;
  width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center;
  font-size: 12px; font-weight: 600; color: var(--marinho); background: var(--papel); border: 1px solid var(--linha-forte);
}
.side-note { margin-top: auto; padding-top: 16px; font-size: 12.5px; line-height: 1.5; color: var(--muted); }

/* ---------------------------------------------------------------- painel da conversa */
.chat {
  min-width: 0; min-height: 0; display: flex; flex-direction: column;
  background: var(--papel); border: 1px solid var(--linha); border-radius: 16px;
  box-shadow: 0 1px 2px rgba(14, 42, 71, .05);
  overflow: hidden;
}
.messages { flex: 1; min-height: 0; overflow-y: auto; scroll-behavior: smooth; }
.thread {
  max-width: 780px; margin: 0 auto; padding: 32px 28px 24px;
  display: flex; flex-direction: column; gap: 14px; min-height: 100%;
}

/* boas-vindas */
.welcome { margin: auto 0; padding: 8px 0 16px; }
.welcome-mark {
  width: 48px; height: 48px; border-radius: 14px; display: grid; place-items: center;
  background: var(--marinho); color: #fff; margin-bottom: 18px;
}
.welcome-mark svg { width: 30px; height: 30px; stroke-width: 1.9; }
.welcome h2 {
  margin: 0 0 8px; font: 600 27px/1.2 var(--font-display); letter-spacing: -0.015em; color: var(--marinho);
}
.welcome > p { max-width: 60ch; color: var(--muted); font-size: 15.5px; }
.suggest-grid { margin-top: 28px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.suggest-group { display: flex; flex-direction: column; gap: 8px; }
.suggest-group h3 {
  margin: 0 0 2px; display: flex; align-items: center; gap: 8px;
  font: 600 13.5px/1.3 var(--font); color: var(--tinta);
}
.suggestion {
  text-align: left; cursor: pointer; padding: 10px 12px; border-radius: 10px;
  background: var(--papel); border: 1px solid var(--linha);
  font-size: 13.5px; line-height: 1.45; color: var(--tinta-2);
  transition: border-color .15s ease, background-color .15s ease, color .15s ease;
}
@media (hover: hover) and (pointer: fine) {
  .suggestion:hover { border-color: var(--d); background: var(--d-suave); color: var(--tinta); }
}

/* entrada de novas mensagens: só opacidade + 6px, sem atrasar quem lê */
.row, .route {
  transition: opacity .22s var(--ease-out), transform .22s var(--ease-out);
  @starting-style { opacity: 0; transform: translateY(6px); }
}

/* mensagem do usuário */
.row-user { display: flex; justify-content: flex-end; margin-top: 10px; }
.row-user:first-child { margin-top: 0; }
.bubble-user {
  max-width: min(78%, 560px); padding: 10px 15px; border-radius: 16px 16px 4px 16px;
  background: var(--marinho); color: #fff; overflow-wrap: anywhere; line-height: 1.5;
}

/* linha de encaminhamento (orquestração) */
.route {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding-left: 48px; font-size: 13px; color: var(--muted);
}
.route .icon { width: 16px; height: 16px; color: var(--d); margin-left: -24px; }
.route strong { color: var(--d); font-weight: 600; }
.route-conf {
  font-size: 12px; padding: 1px 8px; border-radius: 999px; background: var(--papel-2); border: 1px solid var(--linha);
}

/* mensagem de um agente */
.row-bot { display: flex; gap: 12px; align-items: flex-start; }
.bot-body { min-width: 0; flex: 1; max-width: 640px; }
.bot-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; min-height: 22px; margin-bottom: 5px; }
.bot-name { font-weight: 600; font-size: 14px; color: var(--tinta); }
.chip {
  display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 500;
  padding: 1px 9px; border-radius: 999px; background: var(--papel-2); color: var(--tinta-2); border: 1px solid var(--linha);
}
.chip.attention { background: #fff7e6; border-color: #f2dcae; color: #7a5310; }
.chip.denied { background: var(--perigo-suave); border-color: #f4c8c2; color: #8f1d14; }

.bubble-bot {
  position: relative; padding: 14px 16px; border-radius: 4px 16px 16px 16px;
  background: var(--papel); border: 1px solid var(--linha); overflow-wrap: anywhere;
}
.answer { color: var(--tinta); }
.answer > * + * { margin-top: 10px; }
.answer p { line-height: 1.62; }
.answer strong { font-weight: 600; color: var(--tinta); }
.answer ul, .answer ol { margin: 0; padding-left: 22px; display: flex; flex-direction: column; gap: 4px; }
.answer li { line-height: 1.55; padding-left: 2px; }
.answer li::marker { color: var(--d, var(--muted)); }
.answer .label {
  display: flex; align-items: center; gap: 7px; margin-top: 16px;
  font-size: 13px; color: var(--muted);
}
.answer .label::before {
  content: ""; width: 3px; height: 14px; border-radius: 2px; background: var(--d, var(--linha-forte));
}
.answer .label strong { color: var(--tinta-2); }
.answer .label:first-child { margin-top: 0; }
.answer .criteria { font-size: 13px; color: var(--muted); }
.answer .pending { display: none; }

/* cursor de digitação: barra fixa que acompanha o texto */
.caret {
  display: inline-block; width: 2px; height: 1.05em; margin-left: 2px; vertical-align: -0.15em;
  border-radius: 1px; background: var(--d, var(--ceu));
}

.bubble-foot { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--linha); display: flex; flex-direction: column; gap: 10px; }
.reveal { opacity: 0; transform: translateY(4px); transition: opacity .2s var(--ease-out), transform .2s var(--ease-out); }
.reveal.is-in { opacity: 1; transform: none; }
.mode { display: flex; align-items: center; gap: 7px; font-size: 12.5px; color: var(--muted); }
.mode .icon { width: 15px; height: 15px; color: var(--d); }
.notice { font-size: 13px; color: #6b4a0e; background: #fff7e6; border: 1px solid #f2dcae; border-radius: 8px; padding: 7px 10px; }

.sources { border-radius: 10px; background: var(--papel-2); border: 1px solid var(--linha); }
.sources summary {
  list-style: none; cursor: pointer; display: flex; align-items: center; gap: 8px;
  padding: 8px 12px; font-size: 13px; font-weight: 600; color: var(--marinho-2); border-radius: 10px;
}
.sources summary::-webkit-details-marker { display: none; }
.sources summary .icon { width: 16px; height: 16px; color: var(--d); }
.sources summary::after {
  content: ""; margin-left: auto; width: 7px; height: 7px;
  border-right: 1.6px solid var(--muted); border-bottom: 1.6px solid var(--muted);
  transform: translateY(-2px) rotate(45deg); transition: transform .18s var(--ease-out);
}
.sources[open] summary::after { transform: translateY(2px) rotate(-135deg); }
.sources ol { margin: 0; padding: 2px 12px 12px; list-style: none; display: flex; flex-direction: column; gap: 10px; }
.src-head { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; font-size: 13px; }
.src-doc { font-weight: 600; color: var(--tinta); overflow-wrap: anywhere; }
.src-meta { color: var(--muted); font-size: 12px; }
.src-excerpt {
  margin-top: 4px; padding: 8px 10px; border-radius: 8px; background: var(--papel); border: 1px solid var(--linha);
  font-size: 12.5px; line-height: 1.5; color: var(--tinta-2);
}

/* indicador de digitação */
.typing .bubble-bot { display: inline-flex; align-items: center; padding: 13px 16px; }
.dots { display: inline-flex; gap: 5px; }
.dots i { width: 7px; height: 7px; border-radius: 50%; background: var(--d, var(--aur)); opacity: .35; animation: typing-dot 1.1s infinite ease-in-out; }
.dots i:nth-child(2) { animation-delay: .15s; }
.dots i:nth-child(3) { animation-delay: .3s; }
@keyframes typing-dot {
  0%, 60%, 100% { transform: translateY(0); opacity: .35; }
  30% { transform: translateY(-4px); opacity: 1; }
}
.typing-caption { margin-top: 6px; font-size: 12.5px; color: var(--muted); }

/* erro */
.row-error .bubble-bot { background: var(--perigo-suave); border-color: #f4c8c2; color: #7a1a12; }
.row-error .err { display: flex; gap: 8px; align-items: flex-start; }
.row-error .err .icon { color: var(--perigo); margin-top: 3px; }
.retry {
  margin-top: 10px; height: 32px; padding: 0 12px; border-radius: 8px; cursor: pointer;
  background: #fff; border: 1px solid #f4c8c2; color: var(--perigo); font-size: 13px; font-weight: 500;
}
.retry:hover { background: #fff5f4; }

/* ---------------------------------------------------------------- composer */
.composer { padding: 14px 28px 14px; border-top: 1px solid var(--linha); background: var(--papel); }
.composer-box {
  max-width: 780px; margin: 0 auto; display: flex; align-items: flex-end; gap: 8px;
  padding: 6px 6px 6px 16px; border-radius: 14px; background: var(--papel-2); border: 1px solid var(--linha-forte);
  transition: border-color .15s ease, box-shadow .15s ease, background-color .15s ease;
}
.composer-box:focus-within { border-color: var(--ceu); background: var(--papel); box-shadow: 0 0 0 3px var(--ceu-suave); }
.composer textarea {
  flex: 1; resize: none; border: 0; background: transparent; outline: none;
  min-height: 40px; max-height: 168px; padding: 9px 0; line-height: 1.45;
}
.composer textarea::placeholder { color: #8391a3; }
.send {
  width: 40px; height: 40px; flex: none; border-radius: 10px; border: 0; cursor: pointer;
  display: grid; place-items: center; background: var(--ceu); color: #fff;
  transition: background-color .15s ease, opacity .15s ease, transform .12s var(--ease-out);
}
.send .icon { width: 19px; height: 19px; stroke-width: 2.1; }
.send:not(:disabled):hover { background: var(--ceu-hover); }
.send:not(:disabled):active { transform: scale(0.96); }
.send:disabled { opacity: .4; cursor: not-allowed; }
.composer-hint {
  max-width: 780px; margin: 8px auto 0; display: flex; justify-content: space-between; gap: 12px;
  font-size: 12px; color: var(--muted);
}
.counter { white-space: nowrap; }
.counter.over { color: var(--perigo); font-weight: 600; }

/* ---------------------------------------------------------------- movimento reduzido */
@media (prefers-reduced-motion: reduce) {
  html:focus-within, .messages { scroll-behavior: auto; }
  .row, .route { @starting-style { transform: none; } }
  .reveal { transform: none; }
  .dots i { animation-name: typing-fade; }
  @keyframes typing-fade { 0%, 100% { opacity: .35; } 50% { opacity: 1; } }
}

/* ---------------------------------------------------------------- responsivo */
@media (max-width: 1080px) {
  .suggest-grid { grid-template-columns: 1fr; gap: 16px; }
}
@media (max-width: 900px) {
  .layout { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 12px 16px 16px; }
  .sidebar { padding-top: 0; overflow: visible; }
  .side-heading, .steps, .side-note, .agent-desc, .agent-count { display: none; }
  .agent-list { flex-direction: row; gap: 8px; overflow-x: auto; scrollbar-width: none; }
  .agent { flex: 0 0 auto; align-items: center; gap: 8px; padding: 5px 12px 5px 5px; border: 1px solid var(--linha); border-radius: 999px; background: var(--papel); }
  .agent:first-child { padding-top: 5px; }
  .agent .avatar { width: 26px; height: 26px; }
  .agent .avatar svg { width: 15px; height: 15px; }
  .agent-name { font-size: 13px; white-space: nowrap; }
  .thread { padding: 22px 16px 16px; }
  .composer { padding: 10px 12px 12px; }
}
@media (max-width: 560px) {
  :root { --topbar-h: 56px; }
  .topbar-inner { padding: 0 16px; }
  .brand-text p, .btn-new span { display: none; }
  .btn-new { width: 36px; padding: 0; justify-content: center; }
  .status { font-size: 0; gap: 0; }
  .status::before { width: 9px; height: 9px; }
  .welcome h2 { font-size: 22px; }
  .bubble-user { max-width: 88%; }
  .row-bot { gap: 10px; }
  .row-bot > .avatar { width: 30px; height: 30px; }
  .route { padding-left: 40px; }
  .composer textarea { font-size: 16px; } /* evita zoom automático no iOS */
  .composer-hint span:first-child { display: none; }
}

"use strict";

(() => {
  const API = ""; // mesma origem: o FastAPI serve este frontend
  const MAX_CHARS = 1000;
  const TIMEOUT_MS = 60000;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  // Pausas da "conversa": a Aurora analisa, o agente começa a digitar, o texto aparece.
  const THINK_MS = () => (reduceMotion.matches ? 250 : 650);
  const HANDOFF_MS = () => (reduceMotion.matches ? 200 : 600);
  const MS_PER_CHAR = 16;
  const TYPE_MIN_MS = 500;
  const TYPE_MAX_MS = 2400;

  const AGENT = {
    financeiro: { name: "Agente Financeiro", icon: "i-chart" },
    informacoes_internas: { name: "Agente de Informações Internas", icon: "i-book" },
    ouvidoria: { name: "Agente de Ouvidoria", icon: "i-chat" },
    aurora: { name: "Aurora", icon: "i-aurora" },
  };
  const MODE = {
    deterministic: { text: "Calculado diretamente nos dados da base", icon: "i-calc" },
    extractive: { text: "Trechos dos documentos, sem modelo de IA", icon: "i-quote" },
    llm: { text: "Escrito por IA a partir das fontes", icon: "i-spark" },
  };
  const STATUS = {
    not_found: ["Sem evidência suficiente", "attention"],
    clarification: ["Precisa de mais detalhes", "attention"],
    refused: ["Pedido recusado", "denied"],
    out_of_scope: ["Fora do escopo", "attention"],
  };

  const $ = (sel) => document.querySelector(sel);
  const scroller = $("#messages");
  const thread = $("#thread");
  const welcome = $("#welcome");
  const form = $("#composer");
  const input = $("#question");
  const sendBtn = $("#send");
  const counter = $("#counter");
  const statusEl = $("#service-status");

  let busy = false;
  let controller = null;
  let generation = 0; // muda a cada "Nova conversa": etapas antigas param de agir
  let skipTyping = null;

  // ---------------------------------------------------------------- utilitários

  function el(tag, attrs = {}, children = []) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (v === undefined || v === null || v === false) continue;
      if (k === "class") node.className = v;
      else if (k === "text") node.textContent = v;
      else node.setAttribute(k, v);
    }
    for (const c of [].concat(children)) if (c) node.append(c);
    return node;
  }

  function icon(id) {
    const ns = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(ns, "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("aria-hidden", "true");
    const use = document.createElementNS(ns, "use");
    use.setAttribute("href", `#${id}`);
    svg.append(use);
    return svg;
  }

  function avatar(domain) {
    const info = AGENT[domain] || AGENT.aurora;
    return el("span", { class: "avatar", "aria-hidden": "true" }, icon(info.icon));
  }

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const domainOf = (category) => (AGENT[category] ? category : "aurora");

  function nearBottom() {
    return scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight < 140;
  }
  function scrollToEnd() {
    scroller.scrollTop = scroller.scrollHeight;
  }

  // ---------------------------------------------------------------- texto da resposta (sem innerHTML)

  function inline(text) {
    const frag = document.createDocumentFragment();
    for (const part of text.split(/(\*\*[^*]+\*\*)/g)) {
      if (/^\*\*[^*]+\*\*$/.test(part)) frag.append(el("strong", { text: part.slice(2, -2) }));
      else if (part) frag.append(document.createTextNode(part));
    }
    return frag;
  }

  function renderText(text) {
    const frag = document.createDocumentFragment();
    let list = null;
    let listType = null;
    for (const raw of text.split("\n")) {
      const line = raw.trim();
      const bullet = line.match(/^[-•]\s+(.*)$/);
      const num = line.match(/^(\d+)[.)]\s+(.*)$/);
      if (bullet || num) {
        const type = bullet ? "ul" : "ol";
        if (!list || listType !== type) {
          list = el(type, num && num[1] !== "1" ? { start: num[1] } : {});
          listType = type;
          frag.append(list);
        }
        list.append(el("li", {}, inline(bullet ? bullet[1] : num[2])));
        continue;
      }
      list = null;
      if (!line) continue;
      // "**arquivo.md** (seção)" ou "Fonte: **arquivo**" viram um rótulo de origem
      if (/^\*\*[^*]+\*\*(\s*\([^)]*\))?:?$/.test(line) || /^Fonte: \*\*/.test(line)) {
        frag.append(el("p", { class: "label" }, inline(line)));
      } else if (/^Crit[ée]rio:/.test(line)) {
        frag.append(el("p", { class: "criteria" }, inline(line)));
      } else {
        frag.append(el("p", {}, inline(line)));
      }
    }
    return frag;
  }

  // ---------------------------------------------------------------- blocos da conversa

  function addUser(text) {
    welcome.hidden = true;
    thread.append(el("div", { class: "row row-user" }, el("div", { class: "bubble-user", text })));
    scrollToEnd();
  }

  function buildTyping() {
    let av = avatar("aurora");
    const name = el("span", { class: "bot-name", text: "Aurora" });
    const caption = el("p", { class: "typing-caption", text: "A Aurora está analisando sua pergunta…" });
    const dots = el("span", { class: "dots", "aria-hidden": "true" }, [el("i"), el("i"), el("i")]);
    const node = el("div", { class: "row row-bot typing", "data-domain": "aurora", role: "status" }, [
      av,
      el("div", { class: "bot-body" }, [el("div", { class: "bot-head" }, name), el("div", { class: "bubble-bot" }, dots), caption]),
    ]);
    return {
      node,
      handOff(domain, agentName) {
        node.dataset.domain = domain;
        const next = avatar(domain);
        av.replaceWith(next);
        av = next;
        name.textContent = agentName;
        caption.textContent = `${agentName} está digitando…`;
      },
    };
  }

  function buildRoute(data) {
    const r = data.routing || {};
    const known = data.category !== "indefinido";
    const text = known
      ? [document.createTextNode("A Aurora encaminhou ao "), el("strong", { text: data.agent })]
      : [document.createTextNode(data.status === "clarification"
        ? "A Aurora encontrou mais de um assunto possível"
        : "A Aurora não identificou um assunto atendido pelos agentes")];
    let chip = null;
    if (r.method === "guard") chip = "regra de segurança";
    else if (r.method === "llm") chip = "classificado por IA";
    else if (known && typeof data.confidence === "number") chip = `confiança de ${Math.round(data.confidence * 100)}%`;
    return el("div", { class: "route", "data-domain": domainOf(data.category), title: r.reason || null }, [
      icon("i-route"),
      el("span", {}, text),
      chip ? el("span", { class: "route-conf", text: chip }) : null,
    ]);
  }

  function sourcesBlock(sources) {
    if (!sources || !sources.length) return null;
    const list = el("ol");
    for (const s of sources) {
      const meta = [s.section, s.page ? `página ${s.page}` : null].filter(Boolean).join(", ");
      const score = typeof s.score === "number" && s.score > 0 ? `Relevância BM25: ${s.score.toFixed(2)}` : null;
      list.append(el("li", {}, [
        el("div", { class: "src-head" }, [
          el("span", { class: "src-doc", text: s.document, title: score }),
          meta ? el("span", { class: "src-meta", text: meta }) : null,
        ]),
        el("p", { class: "src-excerpt", text: s.excerpt }),
      ]));
    }
    const n = sources.length;
    return el("details", { class: "sources" }, [
      el("summary", {}, [icon("i-doc"), el("span", { text: n === 1 ? "1 fonte consultada" : `${n} fontes consultadas` })]),
      list,
    ]);
  }

  function buildAnswer(data) {
    const domain = domainOf(data.category);
    const head = el("div", { class: "bot-head" }, el("span", { class: "bot-name", text: data.agent || "Aurora" }));
    const st = STATUS[data.status];
    if (st) head.append(el("span", { class: `chip ${st[1]}`, text: st[0] }));

    const answer = el("div", { class: "answer" }, renderText(data.answer || ""));
    const bubble = el("div", { class: "bubble-bot" }, answer);
    const foot = el("div", { class: "bubble-foot reveal" });
    const mode = MODE[data.mode];
    if (mode) foot.append(el("p", { class: "mode" }, [icon(mode.icon), document.createTextNode(mode.text)]));
    if (data.notice) foot.append(el("p", { class: "notice", text: data.notice }));
    const src = sourcesBlock(data.sources);
    if (src) foot.append(src);
    if (foot.childElementCount) bubble.append(foot);

    const node = el("article", { class: "row row-bot", "data-domain": domain }, [
      avatar(domain), el("div", { class: "bot-body" }, [head, bubble]),
    ]);
    return { node, answer, bubble, foot };
  }

  function buildError(message, retryQuestion) {
    const bubble = el("div", { class: "bubble-bot" }, el("p", { class: "err" }, [icon("i-alert"), el("span", { text: message })]));
    const node = el("div", { class: "row row-bot row-error", "data-domain": "aurora", role: "alert" }, [
      avatar("aurora"),
      el("div", { class: "bot-body" }, [el("div", { class: "bot-head" }, el("span", { class: "bot-name", text: "Aurora" })), bubble]),
    ]);
    if (retryQuestion) {
      const btn = el("button", { class: "retry", type: "button", text: "Tentar novamente" });
      btn.addEventListener("click", () => {
        if (busy) return;
        node.remove();
        ask(retryQuestion, { echo: false });
      });
      bubble.append(btn);
    }
    return node;
  }

  // ---------------------------------------------------------------- digitação

  /** Revela o texto já renderizado, caractere a caractere. Clique ou Esc mostram tudo. */
  function typeOut(answerEl, bubble) {
    const items = [];
    const walker = document.createTreeWalker(answerEl, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) items.push({ node: walker.currentNode, text: walker.currentNode.nodeValue });
    const total = items.reduce((n, it) => n + it.text.length, 0);
    if (reduceMotion.matches || total === 0) return Promise.resolve();

    answerEl.querySelectorAll("p, li, ul, ol").forEach((b) => b.classList.add("pending"));
    for (const it of items) it.node.nodeValue = "";
    const caret = el("span", { class: "caret", "aria-hidden": "true" });
    const duration = Math.min(TYPE_MAX_MS, Math.max(TYPE_MIN_MS, total * MS_PER_CHAR));
    bubble.setAttribute("aria-busy", "true");
    bubble.title = "Clique para mostrar a resposta inteira";

    return new Promise((resolve) => {
      let start = null;
      let raf = 0;
      let done = false;

      const show = (count) => {
        let left = count;
        let last = null;
        for (const it of items) {
          if (left <= 0) break;
          const take = Math.min(it.text.length, left);
          if (it.node.nodeValue.length !== take) it.node.nodeValue = it.text.slice(0, take);
          last = it.node;
          for (let p = it.node.parentElement; p && p !== answerEl; p = p.parentElement) p.classList.remove("pending");
          left -= take;
        }
        if (last && last.nextSibling !== caret) last.after(caret);
      };

      const finish = () => {
        if (done) return;
        done = true;
        cancelAnimationFrame(raf);
        for (const it of items) it.node.nodeValue = it.text;
        answerEl.querySelectorAll(".pending").forEach((b) => b.classList.remove("pending"));
        caret.remove();
        bubble.removeAttribute("aria-busy");
        bubble.removeAttribute("title");
        bubble.removeEventListener("click", finish);
        skipTyping = null;
        resolve();
      };

      const frame = (t) => {
        if (start === null) start = t;
        const stick = nearBottom();
        const progress = Math.min(1, (t - start) / duration); // velocidade constante: linear
        show(Math.ceil(total * progress));
        if (stick) scrollToEnd();
        if (progress >= 1) finish();
        else raf = requestAnimationFrame(frame);
      };

      skipTyping = finish;
      bubble.addEventListener("click", finish);
      raf = requestAnimationFrame(frame);
    });
  }

  // ---------------------------------------------------------------- envio

  function setBusy(value) {
    busy = value;
    const n = input.value.trim().length;
    sendBtn.disabled = value || n === 0 || input.value.length > MAX_CHARS;
  }

  async function request(question) {
    controller = new AbortController();
    const timer = setTimeout(() => controller.abort("timeout"), TIMEOUT_MS);
    try {
      const res = await fetch(`${API}/api/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question }),
        signal: controller.signal,
      });
      let body = null;
      try { body = await res.json(); } catch { /* resposta sem JSON */ }
      if (res.ok) return { data: body };
      const detail = body && typeof body.detail === "string" ? body.detail : null;
      if (res.status === 422) return { error: detail || "A pergunta não pôde ser processada. Revise o texto e envie de novo." };
      return { error: detail || `O serviço respondeu com erro ${res.status}. Tente de novo em instantes.`, retry: true };
    } catch {
      if (controller.signal.reason === "reset") return { reset: true };
      if (controller.signal.reason === "timeout") return { error: "A resposta demorou mais de 60 segundos. Tente de novo.", retry: true };
      checkHealth();
      return { error: "Não foi possível conectar ao serviço. Verifique se a API está em execução e tente de novo.", retry: true };
    } finally {
      clearTimeout(timer);
      controller = null;
    }
  }

  async function ask(question, { echo = true } = {}) {
    if (busy) return; // impede envios duplicados
    const gen = generation;
    if (echo) addUser(question);
    setBusy(true);

    const typing = buildTyping();
    thread.append(typing.node);
    scrollToEnd();

    try {
      const started = performance.now();
      const result = await request(question);
      await sleep(Math.max(0, THINK_MS() - (performance.now() - started)));
      if (gen !== generation || result.reset) return;

      if (result.error) {
        typing.node.replaceWith(buildError(result.error, result.retry ? question : null));
        scrollToEnd();
        return;
      }

      const data = result.data;
      thread.insertBefore(buildRoute(data), typing.node);
      if (data.category !== "indefinido") {
        typing.handOff(data.category, data.agent);
        scrollToEnd();
        await sleep(HANDOFF_MS());
        if (gen !== generation) return;
      }

      const view = buildAnswer(data);
      typing.node.replaceWith(view.node);
      scrollToEnd();
      await typeOut(view.answer, view.bubble);
      if (gen !== generation) return;
      requestAnimationFrame(() => view.foot.classList.add("is-in"));
    } finally {
      if (gen === generation) setBusy(false);
    }
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const q = input.value.trim();
    if (!q || busy || q.length > MAX_CHARS) return;
    input.value = "";
    updateInput();
    ask(q);
  });

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
      e.preventDefault();
      form.requestSubmit();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && skipTyping) skipTyping();
  });

  function updateInput() {
    const n = input.value.length;
    counter.textContent = n > MAX_CHARS * 0.8 ? `${n}/${MAX_CHARS}` : "";
    counter.classList.toggle("over", n > MAX_CHARS);
    input.style.height = "auto";
    input.style.height = `${Math.min(input.scrollHeight, 168)}px`;
    setBusy(busy);
  }
  input.addEventListener("input", updateInput);

  document.querySelectorAll(".suggestion").forEach((btn) =>
    btn.addEventListener("click", () => ask(btn.textContent.trim())));

  $("#new-chat").addEventListener("click", () => {
    generation += 1;
    if (controller) controller.abort("reset");
    if (skipTyping) skipTyping();
    thread.querySelectorAll(".row, .route").forEach((n) => n.remove());
    welcome.hidden = false;
    input.value = "";
    setBusy(false);
    updateInput();
    scroller.scrollTop = 0;
    input.focus();
  });

  // ---------------------------------------------------------------- estado do serviço

  async function checkHealth() {
    try {
      const res = await fetch(`${API}/health`, { cache: "no-store" });
      const h = await res.json();
      if (h.status !== "ok") {
        statusEl.className = "status warn";
        statusEl.textContent = "Base de conhecimento não indexada";
        statusEl.title = "";
      } else if (h.llm && h.llm.configured) {
        statusEl.className = "status ok";
        statusEl.textContent = "Online com IA";
        statusEl.title = `Provedor: ${h.llm.provider}${h.llm.model ? `, modelo ${h.llm.model}` : ""}`;
      } else {
        statusEl.className = "status ok";
        statusEl.textContent = "Online, sem modelo de IA";
        statusEl.title = (h.llm && h.llm.reason) || "";
      }
    } catch {
      statusEl.className = "status down";
      statusEl.textContent = "Serviço indisponível";
      statusEl.title = "";
    }
  }

  async function loadCounts() {
    try {
      const st = await (await fetch(`${API}/api/knowledge/status`)).json();
      document.querySelectorAll(".agent").forEach((agent) => {
        const d = st.domains && st.domains[agent.dataset.domain];
        const out = agent.querySelector(".agent-count");
        if (!d || !out) return;
        out.textContent = `${d.chunks} trechos de ${d.documents} ${d.documents === 1 ? "arquivo" : "arquivos"}`;
        out.hidden = false;
      });
    } catch { /* indicador opcional */ }
  }

  updateInput();
  checkHealth();
  loadCounts();
})();

